import json
import os
import re
import subprocess
import sys

SKIP_DIRS = {".git", "__pycache__", ".check", ".grade", "node_modules", ".pytest_cache"}


def fail(msg):
    print("FAIL:", msg)
    sys.exit(1)


def read(path):
    try:
        with open(path, encoding="utf-8", errors="replace") as f:
            return f.read()
    except OSError:
        return None


def sha(path):
    try:
        with open(path, "rb") as f:
            return hashlib.sha256(f.read()).hexdigest()
    except OSError:
        return None


def tree(root="."):
    out = []
    for dirpath, dirs, files in os.walk(root):
        dirs[:] = sorted(d for d in dirs if d not in SKIP_DIRS)
        for f in sorted(files):
            if f.endswith(".pyc"):
                continue
            out.append(os.path.relpath(os.path.join(dirpath, f), root).replace(os.sep, "/"))
    return out


def intact(manifest, what="file"):
    """Every path in manifest ({path: sha256}) exists with exactly that content."""
    for path, want in sorted(manifest.items()):
        got = sha(path)
        if got is None:
            fail("%s %s was deleted or moved" % (what, path))
        if got != want:
            fail("%s %s was modified" % (what, path))


