"""Webhook signatures."""
import hashlib
import hmac
import os


def sign(body):
    secret = os.environ.get("WEBHOOK_SECRET")
    if not secret:
        raise RuntimeError("WEBHOOK_SECRET is not set")
    return hmac.new(secret.encode(), body.encode(), hashlib.sha256).hexdigest()

